17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
64	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
65	     */
66	    private static final Pattern EMAIL_PATTERN =
67	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        validateRequiredFields(ownerFieldsDto);
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
119	        rejectDuplicateTelephone(telephone);
120	        owner.setTelephone(telephone);
121	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
131	     * offending field so the client learns about all of them at once.
132	     *
133	     * @param ownerFieldsDto the submitted owner fields
134	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
135	     *                                     missing or blank
136	     */
137	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
138	        List<String> errors = new ArrayList<>();
139	        if (isBlank(ownerFieldsDto.getFirstName())) {
140	            errors.add("firstName");
141	        }
142	        if (isBlank(ownerFieldsDto.getLastName())) {
143	            errors.add("lastName");
144	        }
145	        if (isBlank(ownerFieldsDto.getAddress())) {
146	            errors.add("address");
147	        }
148	        if (isBlank(ownerFieldsDto.getCity())) {
149	            errors.add("city");
150	        }
151	        if (isBlank(ownerFieldsDto.getTelephone())) {
152	            errors.add("telephone");
153	        }
154	        if (!errors.isEmpty()) {
155	            throw new MissingOwnerFieldsException(errors);
156	        }
157	    }
158	
159	    private boolean isBlank(String value) {
160	        return value == null || value.isBlank();
161	    }
162	
163	    /**
164	     * Normalizes a submitted telephone by removing every non-digit character and requiring the
165	     * result to be exactly 10 digits.
166	     *
167	     * @param telephone the raw telephone value as submitted
168	     * @return the 10-digit normalized telephone
169	     * @throws InvalidTelephoneException if the stripped value is not exactly 10 digits
170	     */
171	    private String normalizeTelephone(String telephone) {
172	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
173	        if (digits.length() != 10) {
174	            throw new InvalidTelephoneException(telephone);
175	        }
176	        return digits;
177	    }
178	
179	    /**
180	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
181	     * value is treated as absent and returns {@code null}); when present the value must be a
182	     * syntactically valid address, and is stored and returned lower-cased.
183	     *
184	     * @param email the raw email value as submitted, may be {@code null}
185	     * @return the lower-cased email, or {@code null} when none was supplied
186	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
187	     */
188	    private String normalizeEmail(String email) {
189	        if (email == null || email.isBlank()) {
190	            return null;
191	        }
192	        String normalized = email.trim().toLowerCase();
193	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
194	            throw new InvalidEmailException(email);
195	        }
196	        return normalized;
197	    }
